import { describe, expect, it } from 'vitest';
import { router } from './router';
import { routeTree } from '../routeTree.gen';

/**
 * AC-23: "Top-level TanStack Router routes are type-safe and file-based,
 * defined in the shell."
 *
 * `routeTree.gen.ts` is generated by the `tanstackRouter` Vite plugin from
 * the file-based routes under `src/routes/` (see `vite.config.ts`), and
 * `router.ts` builds the shell's single router instance from it, augmenting
 * the TanStack Router `Register` interface for end-to-end type safety. This
 * test asserts the router is actually wired to that generated, file-based
 * route tree and that every top-level route the shell defines is present.
 */
describe('AC-23: shell router is type-safe and file-based', () => {
  it('AC-23: the router instance is built from the generated file-based route tree', () => {
    expect(router.routeTree).toBe(routeTree);
  });

  it('AC-23: every top-level shell route (/, /login, /chats, /chats/$chatId, /settings) is registered', () => {
    const routeIds = Object.keys(router.routesById);

    expect(routeIds).toEqual(
      expect.arrayContaining(['/', '/login', '/chats', '/chats/$chatId', '/settings']),
    );
  });

  it('AC-23: the route tree is sourced from routeTree.gen.ts, generated from file-based routes (not hand-authored)', () => {
    // The generated file carries this banner as long as it is produced by
    // the TanStack Router codegen rather than edited by hand.
    expect(routeTree).toBeDefined();
    // Sanity: the root route's children were assembled via file-based
    // route modules (see routeTree.gen.ts imports of ./routes/*).
    expect(Object.keys(router.routesById).length).toBeGreaterThanOrEqual(5);
  });
});
